-- Stores the frozen A4Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a4q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A4Q';
 v_cp constant text := 'A4Q_C2';
 v_wi constant bigint := 1114;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A4Q_C2';
 v_packet_sha constant text := '4316a4baa8ed478b8c076c5b1b71e24e11b89fe494d20a4d9b2a93423feb6abb';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"categories":["DIRECT","INDIRECT","CONSUMER","DEPENDENCY"],"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"lists":["direct_impacts","indirect_impacts","consumers","dependency_paths"],"min_distinct_gaps":3,"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001"},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a3_stage_output\": {\n    \"as_is_baseline_or_new_implementation_evidence\": {\n      \"kind\": \"NONE_SUPPLIED\",\n      \"refs\": []\n    },\n    \"authority_binding_refs\": [],\n    \"authority_state\": \"UNKNOWN\",\n    \"currentness_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\"\n    ],\n    \"evidence_items\": [\n      {\n        \"currentness_basis\": \"READ_IN_THIS_RUN\",\n        \"observed_fields\": {\n          \"input_sha256\": \"a1974eae630ef1eea450e6bd95248a73da785257de73b06e13fb727190e76987\",\n          \"packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\",\n          \"request_sha256\": \"a136daa7486437dc62b8757993b5213b3b6b2575bb32cb08e2a5217c84df3071\"\n        },\n        \"read_status\": \"READ\",\n        \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\"\n      },\n      {\n        \"currentness_basis\": \"READ_IN_THIS_RUN\",\n        \"observed_fields\": {\n          \"created_by_execution_id\": \"ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A1Q_C2\",\n          \"evento_tipo\": \"HANDOFF_DEEP_CONTEXT\",\n          \"payload_packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\"\n        },\n        \"read_status\": \"READ\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      }\n    ],\n    \"implementation_state\": \"UNKNOWN\",\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A3_TARGETED_EVIDENCE_OUTPUT_V1\",\n    \"source_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\"\n    ],\n    \"stop_reason\": \"Se completó la investigación mínima autorizada: dos fuentes consultadas, dos lecturas satisfactorias y coincidencia exacta entre packet_sha256 y payload_packet_sha256. READ_IN_THIS_RUN acredita la consulta de esas fuentes, no la vigencia de la autoridad del objetivo. Ambas fuentes documentan el traspaso del pipeline de análisis y no resuelven las ocho brechas materiales identificadas. No corresponde declarar SUFFICIENT, inferir una solución técnica ni fabricar una línea base AS-IS. Se detiene la investigación al alcanzar el límite de las dos fuentes suministradas.\",\n    \"sufficiency_verdict\": \"NEED_MORE_EVIDENCE\",\n    \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\",\n    \"target_resolution\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"implementation_state\": \"UNKNOWN\",\n      \"reason\": \"Las dos fuentes fueron leídas y los hashes de paquete coinciden exactamente. Sin embargo, ambas describen el paquete de entrada y su evento de traspaso, no la autoridad funcional ni la implementación del objetivo. No existe evidencia suministrada que permita identificar el objeto funcional exacto, su autoridad vigente, su implementación actual o su inexistencia.\",\n      \"resolved\": false\n    },\n    \"unresolved_material_gaps\": [\n      {\n        \"gap_code\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"statement\": \"No se identifica la capacidad funcional canónica, pantalla, canal o segmento exacto afectado por la solicitud.\"\n      },\n      {\n        \"gap_code\": \"TARGET_AUTHORITY_NOT_SUPPLIED\",\n        \"statement\": \"No se suministran reglas, contratos o decisiones vigentes que acrediten la autoridad funcional aplicable a la comunicación del ahorro.\"\n      },\n      {\n        \"gap_code\": \"IMPLEMENTATION_STATE_UNVERIFIED\",\n        \"statement\": \"No se aporta evidencia que demuestre si la funcionalidad existe actualmente o si se trata de una implementación nueva.\"\n      },\n      {\n        \"gap_code\": \"AS_IS_BASELINE_MISSING\",\n        \"statement\": \"No existe una línea base verificable del comportamiento actual ni evidencia que permita identificar el cambio respecto de ese comportamiento.\"\n      },\n      {\n        \"gap_code\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"statement\": \"No se define el significado del ahorro, su importe de comparación ni las condiciones bajo las cuales puede comunicarse.\"\n      },\n      {\n        \"gap_code\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"statement\": \"No está acreditado el estado de la oferta ni el momento exacto anterior a la aceptación en el que corresponde informar el ahorro.\"\n      },\n      {\n        \"gap_code\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"statement\": \"No se dispone de una definición autorizada del monto de la cuota ni de su relación con el ahorro.\"\n      },\n      {\n        \"gap_code\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"statement\": \"No se aportan criterios verificables que permitan determinar si los clientes comprenden la diferencia entre ahorro y cuota.\"\n      }\n    ]\n  }\n}","input_origin":"A3Q_C2 GPT Native RAW (raw_output_sha256 30150806da0208b9e9e3caad77878e7faa930fc6b7293ef7ee0e82782ea29e0a)","input_sha256":"54adbc63de58eadd185f2dda2acee9428b03d2f52c38ad8dee4d235a26765b61","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","direct_impacts","indirect_impacts","consumers","dependency_paths","evidence_refs","unresolved_material_impacts","impact_statement","no_absence_claimed"],"schema":"A4_IMPACT_MAP_OUTPUT_V1","validator":"analysis_qualification_a4q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"4316a4baa8ed478b8c076c5b1b71e24e11b89fe494d20a4d9b2a93423feb6abb","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A4 (mapa de impacto) del perfil de análisis. Recibes la salida de la etapa A3 (abajo). Enumera los efectos directos e indirectos, consumidores y dependencias del cambio SOLO si la evidencia suministrada los respalda. Si no se conocen, enumera las incógnitas por categoría; NUNCA afirmes que no hay impactos, consumidores o dependencias. No inventes consumidores, rutas de dependencia ni fuentes. Las únicas referencias válidas son las source_refs de la entrada y 'gap:<gap_code>' para cada brecha de la entrada. No infieras solución técnica. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, direct_impacts, indirect_impacts, consumers, dependency_paths, evidence_refs, unresolved_material_impacts, impact_statement, no_absence_claimed. schema_version='A4_IMPACT_MAP_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. direct_impacts, indirect_impacts, consumers, dependency_paths: listas (cada elemento, si lo hay, debe ser {statement, evidence_refs} con referencias válidas; déjalas vacías si ninguna evidencia suministrada respalda un elemento). evidence_refs: lista no vacía de referencias válidas. unresolved_material_impacts: lista de {impact_id (único), category (DIRECT|INDIRECT|CONSUMER|DEPENDENCY), statement (texto), gap_ref (un gap_code de la entrada)}; debe haber al menos una por cada una de las cuatro categorías y deben cubrir al menos 3 brechas distintas. impact_statement: texto que explica qué no se puede afirmar y por qué. no_absence_claimed=true.\n\nENTRADA (JSON):\n{\n  \"a3_stage_output\": {\n    \"as_is_baseline_or_new_implementation_evidence\": {\n      \"kind\": \"NONE_SUPPLIED\",\n      \"refs\": []\n    },\n    \"authority_binding_refs\": [],\n    \"authority_state\": \"UNKNOWN\",\n    \"currentness_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\"\n    ],\n    \"evidence_items\": [\n      {\n        \"currentness_basis\": \"READ_IN_THIS_RUN\",\n        \"observed_fields\": {\n          \"input_sha256\": \"a1974eae630ef1eea450e6bd95248a73da785257de73b06e13fb727190e76987\",\n          \"packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\",\n          \"request_sha256\": \"a136daa7486437dc62b8757993b5213b3b6b2575bb32cb08e2a5217c84df3071\"\n        },\n        \"read_status\": \"READ\",\n        \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\"\n      },\n      {\n        \"currentness_basis\": \"READ_IN_THIS_RUN\",\n        \"observed_fields\": {\n          \"created_by_execution_id\": \"ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A1Q_C2\",\n          \"evento_tipo\": \"HANDOFF_DEEP_CONTEXT\",\n          \"payload_packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\"\n        },\n        \"read_status\": \"READ\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      }\n    ],\n    \"implementation_state\": \"UNKNOWN\",\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A3_TARGETED_EVIDENCE_OUTPUT_V1\",\n    \"source_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\"\n    ],\n    \"stop_reason\": \"Se completó la investigación mínima autorizada: dos fuentes consultadas, dos lecturas satisfactorias y coincidencia exacta entre packet_sha256 y payload_packet_sha256. READ_IN_THIS_RUN acredita la consulta de esas fuentes, no la vigencia de la autoridad del objetivo. Ambas fuentes documentan el traspaso del pipeline de análisis y no resuelven las ocho brechas materiales identificadas. No corresponde declarar SUFFICIENT, inferir una solución técnica ni fabricar una línea base AS-IS. Se detiene la investigación al alcanzar el límite de las dos fuentes suministradas.\",\n    \"sufficiency_verdict\": \"NEED_MORE_EVIDENCE\",\n    \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\",\n    \"target_resolution\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"implementation_state\": \"UNKNOWN\",\n      \"reason\": \"Las dos fuentes fueron leídas y los hashes de paquete coinciden exactamente. Sin embargo, ambas describen el paquete de entrada y su evento de traspaso, no la autoridad funcional ni la implementación del objetivo. No existe evidencia suministrada que permita identificar el objeto funcional exacto, su autoridad vigente, su implementación actual o su inexistencia.\",\n      \"resolved\": false\n    },\n    \"unresolved_material_gaps\": [\n      {\n        \"gap_code\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"statement\": \"No se identifica la capacidad funcional canónica, pantalla, canal o segmento exacto afectado por la solicitud.\"\n      },\n      {\n        \"gap_code\": \"TARGET_AUTHORITY_NOT_SUPPLIED\",\n        \"statement\": \"No se suministran reglas, contratos o decisiones vigentes que acrediten la autoridad funcional aplicable a la comunicación del ahorro.\"\n      },\n      {\n        \"gap_code\": \"IMPLEMENTATION_STATE_UNVERIFIED\",\n        \"statement\": \"No se aporta evidencia que demuestre si la funcionalidad existe actualmente o si se trata de una implementación nueva.\"\n      },\n      {\n        \"gap_code\": \"AS_IS_BASELINE_MISSING\",\n        \"statement\": \"No existe una línea base verificable del comportamiento actual ni evidencia que permita identificar el cambio respecto de ese comportamiento.\"\n      },\n      {\n        \"gap_code\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"statement\": \"No se define el significado del ahorro, su importe de comparación ni las condiciones bajo las cuales puede comunicarse.\"\n      },\n      {\n        \"gap_code\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"statement\": \"No está acreditado el estado de la oferta ni el momento exacto anterior a la aceptación en el que corresponde informar el ahorro.\"\n      },\n      {\n        \"gap_code\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"statement\": \"No se dispone de una definición autorizada del monto de la cuota ni de su relación con el ahorro.\"\n      },\n      {\n        \"gap_code\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"statement\": \"No se aportan criterios verificables que permitan determinar si los clientes comprenden la diferencia entre ahorro y cuota.\"\n      }\n    ]\n  }\n}","request_sha256":"eeb57d936fa16bf775963e0c33de853ded0b9fa08a1cc8505bb986cd48a9e6a4","run_id":"A4Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A4","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A4Q/A4Q_C2","unit":"A4"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A4Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A4Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A4Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A4Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A4Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A4Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A4Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A4Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A4Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A4Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A4Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A4Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A4Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A4Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A4Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A4Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A4Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a4q_c2_prep$;
COMMIT;
